"""Acceptance criterion 9: the improved thermal model (M-005, single-node RC with pooled priors) evaluated against the Phase A representation (M-001: derived hourly heat demand, constant 21 C).

Phase A: heat demand is the derived series (heat pump electricity x modeled COP, SPF-anchored), indoor temperature a constant placeholder; a controller can only use tanks.
Phase B RC: heat is generated by the RC model under a thermostat (heat pump limited by its nominal output), with indoor temperature dynamics; energy level calibrated to the derived annual heat.
There is NO measured indoor temperature or thermal output, so this is a comparison between two models of the same buildings, not a validation against observation (ISS-004).
Run: PYTHONPATH=. cl/bin/python swiss/validation/compare_rc_phase_a.py     Output: docs/experiments/validation_reports/rc_vs_phase_a.{json,md}
"""
import json
import os
import sys

import numpy as np
import pandas as pd

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
sys.path.insert(0, ROOT)
from swiss.models.rc_building import PRIORS, simulate_ideal  # noqa: E402

CAN = os.path.join(ROOT, 'data', 'canonical')
ROLES = ['SFH-low', 'SFH-mid', 'SFH-high', 'MFH-small', 'MFH-medium', 'MFH-large']
OUT = os.path.join(ROOT, 'docs', 'experiments', 'validation_reports')


def main():
    w = pd.read_csv(os.path.join(CAN, 'weather_klo_2023_hourly.csv'), parse_dates=['timestamp_utc'])
    ta, ghi = w.temp_c.to_numpy(), (w.beam_horizontal_wm2.fillna(0).clip(lower=0) + w.diffuse_wm2.fillna(0).clip(lower=0)).to_numpy()
    idx = pd.DatetimeIndex(w.timestamp_utc).tz_convert('Europe/Zurich')
    params = json.load(open(os.path.join(CAN, 'rc', 'rc_params_2023.json')))['buildings']
    res = {}
    for role in ROLES:
        d = pd.read_csv(os.path.join(CAN, 'thermal', f'{role}_2023_thermal_hourly.csv'))
        derived = d.heating_demand_kwh.to_numpy()
        hp = json.load(open(os.path.join(CAN, 'thermal', 'thermal_params.json')))
        q, T = simulate_ideal(params[role]['effective_area_m2'], ta, ghi)        # RC thermostat, unlimited device (kW = kWh per hour)
        sr = pd.Series(derived, index=idx); sq = pd.Series(q, index=idx)
        daily = (sr.resample('1D').sum().corr(sq.resample('1D').sum()))
        monthly_d, monthly_q = sr.resample('MS').sum(), sq.resample('MS').sum()
        res[role] = {'annual_derived_kwh': float(derived.sum()), 'annual_rc_kwh': float(q.sum()),
                     'hourly_corr': float(np.corrcoef(derived, q)[0, 1]), 'daily_corr': float(daily),
                     'monthly_max_abs_rel_diff_pct': float(100 * np.abs(monthly_q / monthly_d.replace(0, np.nan) - 1).dropna().max()),
                     'peak_kw_derived': float(derived.max()), 'peak_kw_rc': float(q.max()), 'p99_kw_derived': float(np.percentile(derived, 99)), 'p99_kw_rc': float(np.percentile(q, 99)),
                     'hours_heating_derived': int((derived > 0.01).sum()), 'hours_heating_rc': int((q > 0.01).sum()),
                     'mean_abs_hour_to_hour_change_derived': float(np.abs(np.diff(derived)).mean()), 'mean_abs_hour_to_hour_change_rc': float(np.abs(np.diff(q)).mean()),
                     'indoor_hours_above_24c_free_gain': int((T > 24).sum()), 'indoor_mean_c': float(T.mean())}
    json.dump(res, open(os.path.join(OUT, 'rc_vs_phase_a.json'), 'w'), indent=1)
    L = ['# Improved thermal model (M-005, RC) against the Phase A representation (M-001)', '',
         'Generated by `swiss/validation/compare_rc_phase_a.py`. **No measured indoor temperature or thermal output exists** (ISS-004): this compares two models of the same buildings; the RC energy level is calibrated to the derived annual heat, so annual totals agree by construction.', '',
         '| Building | Annual heat derived / RC (kWh_th) | Hourly r | Daily r | Largest monthly deviation | Peak derived / RC (kW) | 99th percentile derived / RC (kW) | Hours heating derived / RC | Mean hour-to-hour change derived / RC (kW) |', '|---|---|---|---|---|---|---|---|---|']
    for role, r in res.items():
        L.append(f'| {role} | {r["annual_derived_kwh"]:.0f} / {r["annual_rc_kwh"]:.0f} | {r["hourly_corr"]:.2f} | {r["daily_corr"]:.2f} | {r["monthly_max_abs_rel_diff_pct"]:.0f} % | {r["peak_kw_derived"]:.1f} / {r["peak_kw_rc"]:.1f} | {r["p99_kw_derived"]:.1f} / {r["p99_kw_rc"]:.1f} | {r["hours_heating_derived"]} / {r["hours_heating_rc"]} | {r["mean_abs_hour_to_hour_change_derived"]:.2f} / {r["mean_abs_hour_to_hour_change_rc"]:.2f} |')
    L += ['', 'Reading the table: the daily correlation is high (0.75 to 0.97) because both follow outdoor temperature, the hourly correlation is low (0.15 to 0.67) because the derived series carries electrical noise (hot-water and defrost events, 15-minute meter lumps) that a heat-loss model does not reproduce; the derived peaks (up to 108 kW for MFH-medium) are 1.7 to 3 times the RC peaks, in line with ISS-030 (derived peaks are probably too high); a monthly deviation of 100 % means a summer month where the derived series still shows space-heating electricity (ISS-027) and the RC model none.', '', '## What changes for controllers',
          '- Phase A (M-001): the demand profile is the derived hourly series with its noise (defrost, hot-water leakage, SPF error); a controller can only act through tanks; no comfort quantity exists.',
          '- RC (M-005): the demand responds to outdoor temperature and sun with a time constant of about 30 h, is smoother (see hour-to-hour change), and the building mass becomes a storage the controller can use within a comfort band; comfort violations exist. The exact ceiling for S3 shows the building mass adds 1.6 points on top of tanks and battery (D-039).',
          '- Not captured by either: part-load and cycling effects (ISS-034), cooling and overheating behaviour (the RC model has no cooling: indoor temperature exceeds 24 C in about 2,700 hours a year under a heating-only thermostat), between-building differences in mass and insulation (pooled priors, A-018), real occupant behaviour.', '']
    open(os.path.join(OUT, 'rc_vs_phase_a.md'), 'w', encoding='utf-8').write('\n'.join(L))
    print('\n'.join(L[:14]))


if __name__ == '__main__':
    main()
